-- ========================================================

local timeScales = {0.5, 1, 2, 4}
local texts = {"0.5X", "1X", "2X", "4X"}




-- ========================================================


function DebugBoxSpeedButton:__init(debugBox_, speedButton_)

    self.debugBox = debugBox_ -- DebugBox
    self.speedButton = speedButton_ -- Button

    local comps = self.speedButton:GetComponentsInChildren(typeof(TMP_Text),true) -- 包含自己

    self.speedButtonText = nil
    for i=0, comps.Length-1 do 
        local comp = comps[i]

        self.speedButtonText = comp -- TMP_Text
        break
    end
    assert(self.speedButtonText)

    self.speedButton.onClick:AddListener(function()
        self:OnPress()
    end)

    self.originfFixedDeltaTime = Time.fixedDeltaTime
    self.timeScalesIdx = 2 -- int,  Second element
    self:Set()
end



function DebugBoxSpeedButton:__delete()
end



-- =========================================== Self ================================================ --


function DebugBoxSpeedButton:Restart()
    self.timeScalesIdx = 2
    self:Set()
end


function DebugBoxSpeedButton:OnPress()
    self.timeScalesIdx = self.timeScalesIdx + 1
    if self.timeScalesIdx > #timeScales then
        self.timeScalesIdx = 1
    end
    self:Set()
end


function DebugBoxSpeedButton:Set()
    local scale = timeScales[self.timeScalesIdx]
    Time.timeScale = scale
    Time.fixedDeltaTime = self.originfFixedDeltaTime * Time.timeScale
    self.speedButtonText.text = "Speed: " .. texts[self.timeScalesIdx]
end





return DebugBoxSpeedButton

